<div class="row wrapper border-bottom white-bg page-heading"><div class="col-lg-10"><h2>Revisão fiscal em lote</h2><ol class="breadcrumb"><li><a href="<?php echo base_url('loja/grupos-fiscais') ?>">Grupos fiscais</a></li><li class="active"><strong>Revisar sugestões</strong></li></ol></div></div>
<div class="wrapper wrapper-content"><div class="ibox"><div class="ibox-content">
  <form class="form-inline" method="get"><label>Ano&nbsp;</label><input type="number" name="ano" value="<?php echo (int)$ano ?>" class="form-control" style="width:100px"> <button class="btn btn-default">Atualizar</button></form><hr>
  <p><strong><?php echo count($produtos) ?></strong> produtos vendidos no ano sem classificação efetiva. Sugestão não altera a tributação até você aprovar.</p>
  <form method="post" action="<?php echo base_url('loja/aprovar-classificacao-fiscal') ?>"><input type="hidden" name="ano" value="<?php echo (int)$ano ?>"><button class="btn btn-primary" onclick="return confirm('Vincular os produtos selecionados aos grupos escolhidos?')"><i class="fa fa-check"></i> Aprovar selecionados</button><button type="button" id="selecionar-sugeridos" class="btn btn-default">Selecionar sugeridos</button><br><br>
  <div class="table-responsive"><table class="table table-striped table-bordered"><thead><tr><th></th><th>Produto</th><th>Categoria</th><th>Unidades</th><th>Sugestão</th><th>Grupo para aprovar</th></tr></thead><tbody><?php foreach($produtos as $produto): ?><tr>
    <td><input type="checkbox" class="produto-sugerido" name="produtos[]" value="<?php echo (int)$produto->id ?>" <?php echo $produto->grupo_fiscal_sugerido_id ? 'data-sugerido="1"' : '' ?>></td><td>#<?php echo (int)$produto->id ?> — <?php echo html_escape($produto->titulo) ?></td><td><?php echo html_escape($produto->categoria) ?></td><td><?php echo number_format((float)$produto->unidades, 0, ',', '.') ?></td><td><?php echo $produto->grupo_sugerido ? html_escape($produto->grupo_sugerido).' ('.html_escape($produto->grupo_fiscal_sugestao_confianca).')' : '<span class="text-muted">Sem sugestão</span>' ?></td><td><select name="grupos[<?php echo (int)$produto->id ?>]" class="form-control"><option value="">Selecionar</option><?php foreach($grupos_fiscais_nfce as $grupo): ?><option value="<?php echo (int)$grupo->id ?>" <?php echo (int)$produto->grupo_fiscal_sugerido_id === (int)$grupo->id ? 'selected' : '' ?>><?php echo html_escape($grupo->nome) ?></option><?php endforeach ?></select></td>
  </tr><?php endforeach ?></tbody></table></div></form>
</div></div></div>
<script>document.getElementById('selecionar-sugeridos').onclick=function(){var itens=document.querySelectorAll('.produto-sugerido[data-sugerido="1"]');for(var i=0;i<itens.length;i++)itens[i].checked=true;};</script>
